package com.example.statusdrafter.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="notifications") public class Notification { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false,fetch=FetchType.LAZY) @JoinColumn(name="user_id") private User user; @Column(nullable=false,columnDefinition="TEXT") private String message; @Column(nullable=false) private String type; @Column(name="read_status",nullable=false) private boolean readStatus=false; @Column(nullable=false) private LocalDateTime createdAt;
 public Notification(){} public Notification(User u,String m,String t){user=u;message=m;type=t;createdAt=LocalDateTime.now();} public Long getId(){return id;} public User getUser(){return user;} public String getMessage(){return message;} public String getType(){return type;} public boolean isReadStatus(){return readStatus;} public void setReadStatus(boolean v){readStatus=v;} public LocalDateTime getCreatedAt(){return createdAt;} }
